/**
 * Pins the onnxruntime-c pod to the version onnxruntime-react-native was built
 * for. Its podspec depends on "onnxruntime-c" with no version, so a fresh
 * `pod install` (every EAS build) takes the newest one, and the native engine
 * under the pet's voice could change with no change here.
 *
 * ios/ is generated by `expo prebuild`, so the pin lives in this plugin rather
 * than in the Podfile.
 *
 * TEMPORARY (Nov 2026): Microsoft's download host, download.onnxruntime.ai,
 * started serving the wrong TLS certificate, so every EAS build failed at
 * "Install pods". Until it is fixed, the pod comes from podspecs/, whose only
 * changes from the published podspec are where the zip is downloaded from (our
 * Supabase storage, bucket "build-deps") and iOS only: the zip is the one
 * CocoaPods fetched from Microsoft before, with the unused macOS slice left out
 * to fit under Supabase's 50 MB file limit, the iOS slices byte for byte the
 * same. To go back: delete podspecs/ and set USE_MIRROR to false.
 */
const { withDangerousMod } = require('@expo/config-plugins');
const { mergeContents } = require('@expo/config-plugins/build/utils/generateCode');
const fs = require('fs');
const path = require('path');

const ORT_VERSION = require('onnxruntime-react-native/package.json').version;

const USE_MIRROR = true;
const MIRROR_PODSPEC = path.join(__dirname, '..', 'podspecs', 'onnxruntime-c.podspec.json');

module.exports = (config) =>
  withDangerousMod(config, [
    'ios',
    (config) => {
      const podfile = path.join(config.modRequest.platformProjectRoot, 'Podfile');
      let line = `  pod 'onnxruntime-c', '${ORT_VERSION}'`;
      if (USE_MIRROR) {
        const mirrored = require(MIRROR_PODSPEC).version;
        if (mirrored !== ORT_VERSION) {
          throw new Error(`podspecs/onnxruntime-c.podspec.json is ${mirrored}, but onnxruntime-react-native wants ${ORT_VERSION}.`);
        }
        line = `  pod 'onnxruntime-c', :podspec => '${path.relative(config.modRequest.platformProjectRoot, MIRROR_PODSPEC)}'`;
      }
      const contents = fs.readFileSync(podfile, 'utf8');
      const merged = mergeContents({
        src: contents,
        newSrc: line,
        tag: 'vitto-onnxruntime-pin',
        anchor: /use_expo_modules!/,
        offset: 1,
        comment: '#',
      });
      fs.writeFileSync(podfile, merged.contents);
      return config;
    },
  ]);
